--region init
function DreamAdventuresCollectionDialog:InitHandler()
    SetButtonAction(self.BtnReplay, Bind(self, self.BtnReplayOnClickHandler))
    SetButtonAction(self.BtnPlay, Bind(self, self.BtnPlayOnClickHandler))
    SetButtonAction(self.TitleBtnPlay, Bind(self, self.BtnTitlePlayOnClickHandler))
    CfUtils.SetTopCommonCb(function()
        CfUtils.StartCoroutineWithBlocker(function()
            CfUtils.PlayAnimation(self.MainPanel, "ActivityDreamAdventuresCollectMain_Out")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
            Events.Broadcast(Constants.EventNames.DreamAdventuresBackToPreparation)
            CfUtils.ResetNavigatorCustomBackAction()
            CfUtils.DialogBack()
        end)
    end)
end

function DreamAdventuresCollectionDialog:InitData()
    self._dumplingList = DreamAdventuresMgr:GetDumplingIds()
    self._choralScoreList = DreamAdventuresMgr:GetChoralScoreIds()
end

function DreamAdventuresCollectionDialog:InitView()
    DreamAdventuresMgr:StopBGM()
    self:StartTimer()
    self:RefreshTitle()
    self:RefreshDumplings()
    self:RefreshChoralScore()
end
--endregion init

--region handler
---重播按钮点击回调
function DreamAdventuresCollectionDialog:BtnReplayOnClickHandler()
    local conf = DreamAdventuresMgr:GetChoralScoreConf()[self:GetSelectedChoralScoreIndex()]
    if not conf then return end

    local musicId = conf.music
    self:PlayMusic(musicId)
end

---播放按钮点击回调
function DreamAdventuresCollectionDialog:BtnPlayOnClickHandler()
    local conf = DreamAdventuresMgr:GetChoralScoreConf()[self:GetSelectedChoralScoreIndex()]
    if not conf then return end

    if self:GetPlayStatus() == PlayStatus.Play then
        self:PauseMusic()
    elseif self:GetPlayStatus() == PlayStatus.Pause then
        self:ResumeMusic()
    elseif self:GetPlayStatus() == PlayStatus.Stop then
        local musicId = conf.music
        self:PlayMusic(musicId)
    end
end

---标题播放按钮点击回调
function DreamAdventuresCollectionDialog:BtnTitlePlayOnClickHandler()
    CfUtils.StartCoroutineWithBlocker(function()
        local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
        for i, v in ipairs(dumplingConf) do
            local isUnlock = DreamAdventuresMgr:CheckDumplingUnlock(v.id)
            if isUnlock then
                CriWareUtils.PlaySeById(v.dumplingSound)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            end
        end
    end)
end

---曲谱点击回调
function DreamAdventuresCollectionDialog:ChoralScoreOnClickHandler(index)
    if index == self:GetSelectedChoralScoreIndex() then return end

    local choralScoreConf = DreamAdventuresMgr:GetChoralScoreConf()
    local conf = choralScoreConf[index]
    self:SetSelectedChoralScoreIndex(index)
    self:RefreshChoralScoreList()
    local musicId = conf.music
    self:PlayMusic(musicId)
end
--endregion handler

--region private
---刷新标题
function DreamAdventuresCollectionDialog:RefreshTitle()
    local dumplingNum = #self:GetDumplingList()
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    CfUtils.FillText(self.TitleTxtNum, string.format("<color=#FF2CE4>%d<color=#FFFFFF>/%d", dumplingNum, #dumplingConf))
end

---刷新团子
function DreamAdventuresCollectionDialog:RefreshDumplings()
    local dumplingConf = DreamAdventuresMgr:GetDumplingConf()
    for i, v in ipairs(dumplingConf) do
        local node = self.ImgBgMusic:GetChild(i - 1)
        local TxtNote = node:Find("TxtNote")
        local TxtQuestion = node:Find("TxtQuestion")
        if isNotNull(node) then 
            local isUnlock = DreamAdventuresMgr:CheckDumplingUnlock(v.id)
            if isUnlock then
                CfUtils.SetActive(TxtNote, true)
                CfUtils.SetActive(TxtQuestion, false)
                local icon = node:Find("ImgIcon")
                CfUtils.FillImage(icon, v.dumplingIcon)
                CfUtils.FillText(TxtNote, v.scaleName)
                SetButtonAction(node, function ()
                    CfUtils.StartCoroutineWithBlocker(function()
                        local go = GameUtils.LoadBundleAsyncById(Constants.UIModulePrefabsIds.ActivityDreamCollectionTipsNode, self.controller, false)
                        local env = CfUtils.GetLuaScr(go, "Game.Activity.DreamAdventures.DreamAdventuresCollectionTipsNode")
                        env:RefreshNode(v)
                        env:FixBoardPosition(icon)
                    end)
                end)
            else
                CfUtils.SetActive(TxtNote, false)
                CfUtils.SetActive(TxtQuestion, true)
            end
        end
    end
end

---刷新曲谱
function DreamAdventuresCollectionDialog:RefreshChoralScore()
    local choralScoreNum = #self:GetChoralScoreList()
    local choralScoreConf = DreamAdventuresMgr:GetChoralScoreConf()
    CfUtils.FillText(self.CollectionTxtNum, string.format("<color=#FF2CE4>%d<color=#FFFFFF>/%d", choralScoreNum, #choralScoreConf))
    
    self:RefreshChoralScoreList()
    self:RefreshChoralScoreInfo()
end

---刷新曲谱列表
function DreamAdventuresCollectionDialog:RefreshChoralScoreList()
    local choralScoreConf = DreamAdventuresMgr:GetChoralScoreConf()
    local selectedIndex = self:GetSelectedChoralScoreIndex()    
    for i, v in ipairs(choralScoreConf) do  
        local node = self.SongLayout:GetChild(i - 1)
        if isNotNull(node) then
            local ImgSel = node:Find("ImgSel")
            CfUtils.SetActive(ImgSel, i == selectedIndex)
            local btnPlay = node:Find("BtnPlay")
            local TxtSongName = btnPlay:Find("TxtSongName")
            if DreamAdventuresMgr:CheckChoralScoreUnlock(v.id) then
                CfUtils.FillText(TxtSongName, v.name)
                CfUtils.SetUISwitchText(TxtSongName, 1)
                SetButtonAction(btnPlay, Bind(self, self.ChoralScoreOnClickHandler, i))
            else
                CfUtils.FillText(TxtSongName, v.promptName)
                CfUtils.SetUISwitchText(TxtSongName, 2)
            end
        end
    end
end

---播放音乐
function DreamAdventuresCollectionDialog:PlayMusic(musicId)
    if self:GetSoundSlice() then
        self:GetSoundSlice().onFinish = nil
        CriWareUtils.StopAll()
    end
    
    CfUtils.StartCoroutineWithBlocker(function()
        self:SetPlayStatus(PlayStatus.Play)
        local soundSlice = CriWareUtils.PlayMusicById(musicId)
        if isNull(soundSlice) then return end
        
        self:SetSoundSlice(soundSlice)
        soundSlice.onFinish = function ()
            self:StopMusic()
        end
        CfUtils.SetActive(self.ImgRecord, false)
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_Play", true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_PlayDefault", true)
        self:RefreshChoralScoreInfo()
    end)
end

function DreamAdventuresCollectionDialog:StopMusic()
    CfUtils.StartCoroutineWithBlocker(function()
        self:SetPlayStatus(PlayStatus.Stop)
        CriWareUtils.StopAll()
        self:SetSoundSlice()
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_Close", true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_CloseDefault", true)
        self:RefreshChoralScoreInfo()
    end)
end

---开启定时器
function DreamAdventuresCollectionDialog:StartTimer()
    self:StopTimer()
    TimerModule.Instance:AddTimer(Constants.TimerName.DreamAdventuresCollectionDialogTimer, 0, 0.1, function()
        if self:GetPlayStatus() == PlayStatus.Play then
            local soundSlice = self:GetSoundSlice()
            if isNotNull(soundSlice) then
                local time = soundSlice:GetPlayback():GetTime()
                if time > 0 then
                    local second = math.floor(time / 1000)
                    local minute = math.floor(second / 60)
                    CfUtils.FillText(self.BtnPlayTxtNum, string.format("%02d:%02d", minute, second))
                else
                    CfUtils.FillText(self.BtnPlayTxtNum, "00:00")
                end
            end
        elseif self:GetPlayStatus() == PlayStatus.Stop then
            CfUtils.FillText(self.BtnPlayTxtNum, "00:00")
        end
    end)
end

---停止定时器
function DreamAdventuresCollectionDialog:StopTimer()
    TimerModule.Instance:RemoveTimer(Constants.TimerName.DreamAdventuresCollectionDialogTimer)
end

---刷新选中的曲谱详情
function DreamAdventuresCollectionDialog:RefreshChoralScoreInfo()
    CfUtils.SetUISwitchText(self.BtnPlayTxtTitle, self:GetPlayStatus() == PlayStatus.Play and 2 or 1)
    CfUtils.SetUISwitchImage(self.BtnPlayImgBg, self:GetPlayStatus() == PlayStatus.Play and 2 or 1)
end

---暂停音乐
function DreamAdventuresCollectionDialog:PauseMusic()
    local soundSlice = self:GetSoundSlice()
    if isNull(soundSlice) then return end

    CfUtils.StartCoroutineWithBlocker(function()
        CriSoundMgr.Pause(soundSlice)
        self:SetPlayStatus(PlayStatus.Pause)
        self:RefreshChoralScoreInfo()   
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_Close", true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_CloseDefault", true)
        self:RefreshChoralScoreInfo()
    end)
end

---恢复音乐
function DreamAdventuresCollectionDialog:ResumeMusic()
    local soundSlice = self:GetSoundSlice()
    if isNull(soundSlice) then return end

    CfUtils.StartCoroutineWithBlocker(function()
        CriSoundMgr.Resume(soundSlice)
        self:SetPlayStatus(PlayStatus.Play)
        self:RefreshChoralScoreInfo()
        
        CfUtils.SetActive(self.ImgRecord, false)
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_Play", true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.35))
        CfUtils.PlayAnimation(self.Records, "ActivityDreamAdventuresCollectMain_Records_PlayDefault", true)
        self:RefreshChoralScoreInfo()
    end)
end

